'QZ_Step_Connect' => '2. Collegare la stampante di etichette via USB e verificare che sia installata nel sistema operativo (Windows: Impostazioni > Stampanti e scanner — macOS: Impostazioni di Sistema > Stampanti e scanner).',
'QZ_Step_Detect' => '3. Fare clic sul pulsante ⟳ accanto a "Nome stampante" qui sopra per rilevare le stampanti di questo computer, quindi selezionare la stampante di etichette. Lasciare il campo vuoto per usare la stampante predefinita del computer.',
'QZ_Step_Cert' => '4. Per stampare senza finestra di autorizzazione, scaricare il certificato qui sotto e copiarlo nella cartella di installazione di QZ Tray, rinominandolo override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Quindi chiudere QZ Tray e riavviarlo.',
'QZ_Step_Test' => '5. Fare clic su "Stampa etichetta di prova" qui sotto. Se QZ Tray chiede l\'autorizzazione, fare clic su Consenti — con il certificato installato non la chiederà più.',
'QZ_Step_Save' => '6. Fare clic su Invia per salvare queste impostazioni. Le etichette della pagina Stampa codice a barre verranno ora stampate direttamente su questa stampante, senza la finestra di stampa del browser.',
'QZ_Setup_Note' => 'QZ Tray viene eseguito sul computer da cui si naviga, quindi funziona anche quando Stocky è ospitato su un server remoto. Ogni computer che stampa etichette deve avere QZ Tray installato.',

// PWA settings tab — installable app identity
'PWA_Enabled' => 'Abilita app installabile',
'PWA_Enabled_Help' => 'Consente ai browser di proporre l\'installazione di questa app su telefoni, tablet e computer e mantiene in cache le pagine utilizzabili offline. Disattivandola si rimuove ovunque la richiesta di installazione e la cache viene svuotata alla visita successiva.',
