'PWA_Short_Name' => 'Nome breve',
'PWA_Short_Name_Help' => 'Mostrato sotto l\'icona nelle schermate home, dove i nomi lunghi vengono troncati. Lasciare vuoto per usare la parte del nome dell\'app prima di "|".',
