'PWA_Reinstall_Notice' => 'I dispositivi che hanno già installato l\'app mantengono il vecchio nome e la vecchia icona finché l\'app non viene disinstallata e reinstallata.',

'Label_Render_Mode' => 'Rendering dell\'etichetta',
'Label_Render_Mode_Hint' => 'Come viene disegnata l\'etichetta. Font della stampante è il metodo più veloce e produce il codice a barre più nitido, ma stampa solo caratteri latini di base con il carattere della stampante. Immagine di anteprima riproduce esattamente il design dell\'etichetta — il font scelto, qualsiasi lingua — come fanno i software dedicati per etichette.',
'Render_Native' => 'Font della stampante (più veloce)',
'Render_Raster' => 'Immagine di anteprima (design esatto)',
'Label_Width_Mm' => 'Larghezza etichetta (mm)',
'Label_Height_Mm' => 'Altezza etichetta (mm)',
'Label_Size_Hint' => 'La dimensione fisica di un\'etichetta adesiva sul rotolo. Deve corrispondere esattamente alle etichette caricate — una dimensione errata fa cercare alla stampante lo spazio tra le etichette nel punto sbagliato, quindi ogni etichetta viene stampata sempre più fuori posizione.',
'Calibrate_Labels' => 'Calibra etichette',
'Calibrate_Labels_Hint' => 'La stampante fa avanzare alcune etichette per misurare l\'adesivo e lo spazio. Eseguire una volta dopo aver caricato un nuovo rotolo o quando le posizioni di stampa si spostano.',
'Calibration_Sent' => 'Calibrazione avviata — la stampante farà avanzare alcune etichette vuote per misurarle. Quando si ferma, eseguire una stampa di prova.',
'Label_Printer_Dpi' => 'Risoluzione della testina di stampa',
'Label_Printer_Dpi_Hint' => 'La maggior parte delle stampanti di etichette è a 203 dpi. Non si è sicuri? Usare il pulsante "Trova risoluzione" qui sotto — stampa la risposta.',
'Find_Resolution' => 'Trova risoluzione',
'Find_Resolution_Hint' => 'Stampa due etichette, contrassegnate 203 e 300. Quella corretta mostra un rettangolo completo sull\'adesivo con un piccolo margine uniforme su tutti e quattro i lati; quella errata ha bordi mancanti o prosegue sull\'adesivo successivo.',
'Dpi_Test_Sent' => 'Sono in stampa due etichette, contrassegnate 203 e 300. Quella corretta mostra un rettangolo completo con un piccolo margine uniforme su tutti e quattro i lati — impostare "Risoluzione della testina di stampa" su quel numero e salvare.',
'Label_Offset_X' => 'Spostamento orizzontale (mm)',
'Label_Offset_X_Hint' => 'Sposta la stampa lateralmente sull\'adesivo. Usarlo quando il testo è tagliato su un bordo laterale — ad es. 2.5 quando l\'adesivo bianco è centrato su una carta di supporto più larga. Regolare a passi di 0.5.',
'Label_Offset_Y' => 'Spostamento verticale (mm)',
'Label_Offset_Y_Hint' => 'Sposta la stampa lungo l\'etichetta. Aumentare quando la parte superiore del design è tagliata o mancante; diminuire quando inizia troppo in basso.',
'Feed_To_Tear' => 'Avanza fino al bordo di strappo',
'Feed_To_Tear_Hint' => 'Fa avanzare l\'etichetta fino alla barra di strappo dopo ogni stampa. Lasciare DISATTIVATO se le etichette vengono stampate spostate verso il basso o divise tra due adesivi — molte stampanti non riavvolgono prima dell\'etichetta successiva.',
