/* ---- Online orders guide (Store > Online Orders) ---- */
'Orders_Guide' => 'Guida agli ordini',
'Ord_Guide_Intro' => 'Come un ordine effettuato nel negozio online arriva al magazzino e alla contabilità, e dove viene effettivamente registrato il denaro.',
'Ord_Guide_Lifecycle_Title' => 'Stato dell\'ordine',
'Ord_Guide_Lifecycle_Pending' => 'Un nuovo ordine in attesa di revisione. Solo un ordine in sospeso può essere confermato o annullato.',
'Ord_Guide_Lifecycle_Confirmed' => 'L\'ordine è stato accettato. Stocky crea una Vendita nel magazzino scelto e scala lo stock — quella vendita è il record da cui leggono i report di stock, pagamenti e profitti.',
'Ord_Guide_Lifecycle_Shipped' => 'L\'ordine è stato spedito. Solo evasione: lo stock è già stato scalato al momento della conferma.',
'Ord_Guide_Lifecycle_Delivered' => 'Il cliente ha ricevuto l\'ordine. È questo che avvia il periodo per il reso.',
'Ord_Guide_Lifecycle_Cancelled' => 'L\'ordine è stato annullato prima della conferma, quindi non è stata creata alcuna vendita e non è stato scalato alcuno stock.',
'Ord_Guide_PaymentStatus_Tip' => 'Impostato al checkout e non modificabile qui. Fare clic per vedere come registrare il pagamento.',
'Ord_Guide_Payment_Title' => 'Stato del pagamento',
'Ord_Guide_Payment_Intro' => 'Questa colonna registra come il cliente ha scelto di pagare al checkout. È impostata dal negozio online e non può essere modificata da questa pagina — il denaro viene tracciato sulla vendita creata dalla conferma dell\'ordine.',
'Ord_Guide_Payment_Paid' => 'Il cliente ha già pagato online tramite un gateway di pagamento. Confermando l\'ordine la vendita viene creata come Pagata e il pagamento viene registrato automaticamente — non serve fare altro.',
'Ord_Guide_Payment_Pending' => 'Contrassegno, bonifico bancario o un altro metodo di pagamento posticipato. Confermando l\'ordine la vendita viene creata come Non pagata, quindi il denaro va registrato manualmente una volta incassato — vedere i passaggi seguenti.',
'Ord_Guide_Payment_Failed' => 'Il gateway ha rifiutato il pagamento o il cliente lo ha abbandonato. L\'ordine viene annullato automaticamente.',
'Ord_Guide_MarkPaid_Title' => 'Passare un pagamento da in sospeso a pagato',
'Ord_Guide_MarkPaid_Step1' => 'Confermare prima l\'ordine qui — è la conferma a creare la vendita.',
'Ord_Guide_MarkPaid_Step2' => 'Aprire Vendite > Tutte le vendite e trovare quella vendita (stesso cliente; la pagina dei dettagli mostra l\'ordine online da cui proviene).',
'Ord_Guide_MarkPaid_Step3' => 'Aprire il menu delle azioni della riga e scegliere Crea pagamento.',
'Ord_Guide_MarkPaid_Step4' => 'Inserire l\'importo, il metodo di pagamento e la data, quindi salvare. La vendita passa automaticamente a Parziale o Pagata, a seconda dell\'importo.',
'Ord_Guide_MarkPaid_Note' => 'Lo stato del pagamento mostrato qui continua a registrare la scelta fatta al checkout e resta invariato. La vendita è il record contabile ed è ciò che alimenta i report di pagamenti e profitti. Usare Mostra pagamenti sulla vendita per rivedere o modificare quanto inserito.',
'Ord_Guide_Notes_Title' => 'Da sapere',
'Ord_Guide_Note_Warehouse' => 'Il magazzino scelto durante la conferma determina da dove viene prelevato lo stock. I magazzini che non possono coprire l\'intero ordine sono contrassegnati come Esaurito in quell\'elenco.',
'Ord_Guide_Note_Preorder' => 'Gli articoli in preordine saltano il controllo dello stock, quindi un ordine che li contiene può essere confermato anche se la quantità non è ancora disponibile.',
'Ord_Guide_Note_Flagged' => 'Un\'etichetta Segnalato indica che l\'ordine ha attivato un controllo antifrode al checkout. Passare il mouse sull\'etichetta per vedere il motivo e rivedere l\'ordine prima di confermarlo.',
'Ord_Guide_Note_Cancel' => 'L\'annullamento è possibile solo finché l\'ordine è in sospeso. Una volta confermato, stornarlo tramite la vendita o un reso cliente.',


