'Guide' => 'Guida',
'Variants_Guide' => 'Guida alle varianti',
'VG_Intro' => 'Un prodotto variabile viene venduto in più varianti. Crearle a partire da opzioni (consigliato) o come semplice elenco di nomi. Ogni variante ha codice, prezzi, immagine e stock propri.',
