'VG_Opt_Step2' => 'Digitare il nome di un\'opzione come Colore o Taglia, oppure sceglierne uno tra i suggerimenti.',
'VG_Opt_Step3' => 'Digitare un valore (ad esempio Rosso) e premere Invio. Ripetere per ogni valore; anche una virgola separa i valori. Fare clic sulla x di un valore per rimuoverlo.',
