'VG_Opt_Step5' => 'Fare clic su "Genera varianti". Viene creata una riga per ogni combinazione e il suo nome viene composto automaticamente, ad esempio "Rosso / S".',
'VG_Opt_Step6' => 'Inserire costo e prezzo su ogni riga, oppure digitare un valore in "Applica a tutti" e fare clic su Costo o Prezzo per copiarlo in tutte le righe.',
'VG_Opt_Step7' => 'I codici vengono generati automaticamente. Digitarne uno proprio o fare clic sull\'icona di aggiornamento per generarne un altro.',
'VG_Opt_Step8' => 'Facoltativo: selezionare "Campioni di colore" su un\'opzione e scegliere un colore per ogni valore; il negozio lo mostra come un pallino colorato.',
'VG_Rows_Title' => 'Righe delle varianti',
'VG_Rows_Text' => 'Ogni riga ha immagine, codice, codice a barre, costo, prezzo, prezzo all\'ingrosso e prezzo minimo di vendita. Durante la creazione di un prodotto è possibile inserire anche lo stock iniziale per magazzino di ogni variante. Un\'etichetta "Incompleta" indica che alla riga manca un valore per un\'opzione.',
'VG_List_Title' => 'Modalità elenco semplice',
'VG_List_Text' => 'Digitare il nome di una variante e premere Invio (o fare clic su Aggiungi) per aggiungere una riga, quindi compilarne codice e prezzi. È il comportamento classico e resta disponibile per i prodotti esistenti.',
'VG_Edit_Title' => 'Modifiche successive',
'VG_Edit_1' => 'Aggiungere un valore e fare clic su "Genera varianti": vengono aggiunte solo le combinazioni mancanti. Le righe esistenti mantengono codici, prezzi e storico.',
'VG_Edit_2' => 'La rimozione di un valore o di un\'opzione rimuove le righe che lo usano. Le righe già salvate vengono eliminate al salvataggio del prodotto, previa conferma.',
'VG_Edit_3' => 'Una variante che ha ancora stock non può essere rimossa. Rettificarne o trasferirne prima lo stock.',
'VG_Edit_4' => 'Il passaggio a "Elenco semplice" mantiene le righe e i loro nomi ma elimina le definizioni delle opzioni.',
'VG_Store_Title' => 'Nel negozio online',
'VG_Store_Text' => 'I clienti scelgono un valore per ogni opzione, ad esempio Colore e poi Taglia. Le combinazioni inesistenti sono disabilitate e quelle esaurite sono barrate. Nel carrello finisce la variante scelta.',
'Choose_Source' => 'Scegli origine',
