'Portal_Quotation_Requests' => 'Richieste di preventivo dal portale',
'Warehouse_Invoice_Address_Help' => 'Indirizzo stampato sulle fatture emesse da questo magazzino. Lasciare vuoto per usare l\'indirizzo aziendale dalle impostazioni.',
'Warehouse_Logo_Help' => 'Logo stampato sulle fatture e sulle ricevute POS di questo magazzino. Lasciare vuoto per usare il logo aziendale.',
'Warehouse_Invoice_Footer_Help' => 'Nota aggiuntiva stampata in fondo alle fatture emesse da questo magazzino.',
'Issued_By' => 'Emesso da',
'Enable_Warehouse_Letterhead' => 'Intestazione del magazzino sulle fatture',
'Enable_Warehouse_Letterhead_Hint' => 'Stampa il magazzino emittente su fatture, ricevute POS e pagina pubblica della fattura: il suo nome sostituisce il nome dell\'azienda, e indirizzo, telefono, email, logo e nota a piè di pagina sostituiscono quelli aziendali. Ogni campo lasciato vuoto nel magazzino ricade sulle impostazioni aziendali globali.',
'Warehouse_Letterhead_Receipt_Notice' => 'L\'intestazione del magazzino è attiva: nome del negozio, indirizzo e telefono stampati su una ricevuta reale provengono dal magazzino che ha emesso la vendita, e la sua nota a piè di pagina viene aggiunta sotto la nota del cliente.',
