'Set_Sidebar_Intro_Title' => 'Trascina e rilascia per riorganizzare la barra laterale',
'Set_Sidebar_Intro_Desc' => 'Riordina i moduli, riordina le voci all\'interno di un modulo o trascina una voce in un modulo diverso. I moduli restano sempre al livello superiore e le voci non possono diventare moduli. La disposizione salvata si applica a tutti gli utenti.',
'Set_Expand_All' => 'Espandi tutto',
'Set_Collapse_All' => 'Comprimi tutto',
'Set_Group_Tag' => 'gruppo',
'Set_Sidebar_Modules_Top_Only' => 'I moduli possono essere riordinati solo al livello superiore.',
'Set_Sidebar_Groups_Under_Module' => 'I gruppi possono essere posizionati solo direttamente sotto un modulo.',
'Set_Sidebar_Items_Inside' => 'Le voci devono rimanere all\'interno di un modulo o di un gruppo.',
'Set_Sidebar_Reset_Confirm' => 'Ripristinare la struttura originale della barra laterale per tutti gli utenti?',
'Set_Filter_Source' => 'Filtra testo di origine…',
