'Upd_Note_Code_Changes_Lost' => 'Nota 1: se sono state apportate modifiche manuali al codice, tali modifiche andranno perse.',
'Upd_Manual_Steps_Intro' => 'Seguire questi passaggi per aggiornare l\'applicazione',
'Upd_Note_Permission_Only' => 'Nota 2: solo un amministratore o un utente con il permesso "{perm}" può aggiornare il sistema',
'Upd_Manual_Step_Backup_Db' => 'Eseguire un backup del database. Andare su {backup}, fare clic su Genera backup — lo si troverà in {path} — oppure esportare il database da PhpMyAdmin e salvarlo sul proprio PC.',
'Upd_Manual_Step_Backup_Files' => 'Eseguire un backup dei file prima dell\'aggiornamento.',
'Upd_Manual_Step_Download' => 'Scaricare l\'ultima versione dal proprio account CodeCanyon ed estrarla.',
'Upd_Manual_Step_Remove' => 'Rimuovere i file precedenti, {except}:',
'Upd_Except' => 'tranne',
'Upd_File_Label' => 'file: {name}',
'Upd_Folder_Label' => 'cartella: {name}',
'Upd_Manual_Step_Reupload' => 'Ricaricare i file e le cartelle del nuovo aggiornamento, {except} gli stessi tre percorsi indicati sopra.',
'Upd_Manual_Step_Visit' => 'Visitare {url} per aggiornare il database.',
'Upd_Manual_Step_Clear_Cache' => 'Svuotare completamente la cache del browser.',
'Upd_Manual_Step_Done' => 'Fatto! Buon lavoro con l\'applicazione aggiornata.',
'Upd_Note_Blank_Pages' => 'Nota: se alcune pagine non si caricano o sono vuote, assicurarsi di aver svuotato la cache del browser.',
'Upd_Guide_Before_Title' => '1. Prima dell\'aggiornamento',
'Upd_Guide_Before_Download' => 'Scaricare il {package} dell\'applicazione dal proprio account CodeCanyon ({path}). Non estrarlo — il programma di aggiornamento richiede lo ZIP esattamente come scaricato.',
'Upd_Latest_Full_Zip' => 'pacchetto ZIP completo più recente',
'Upd_Guide_Before_Admin' => 'Assicurarsi di aver effettuato l\'accesso come amministratore con il permesso {perm}. Nessun altro può vedere o eseguire il programma di aggiornamento.',
'Upd_Guide_Before_Quiet' => 'Scegliere un momento tranquillo: durante l\'aggiornamento l\'applicazione passa per breve tempo in modalità manutenzione e gli altri utenti vengono bloccati.',
'Upd_Guide_Before_No_Manual' => 'Per l\'aggiornamento {not} è necessario eseguire backup manuali, estrarre file, eseguire comandi, modificare file di configurazione o intervenire sul database — il programma di aggiornamento fa tutto automaticamente. (Un backup manuale aggiuntivo, naturalmente, non guasta mai.)',
'Upd_Not' => 'non',
'Upd_Guide_Code_Overwritten' => 'Se il codice dell\'applicazione è stato modificato manualmente, le modifiche verranno sovrascritte dall\'aggiornamento. Dati, file caricati, impostazioni e .env vengono sempre preservati.',
'Upd_Guide_Running_Title' => '2. Esecuzione dell\'aggiornamento',
'Upd_Guide_Run_Open' => 'Aprire {path} (questa pagina) e restare sulla scheda {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: fare clic o trascinare il pacchetto scaricato nell\'area di caricamento. I file di grandi dimensioni vengono caricati in piccoli blocchi, quindi funziona anche su hosting condivisi con limiti di caricamento bassi. Un checksum protegge da caricamenti danneggiati o incompleti.',
'Upd_Upload_The_Zip' => 'Caricare lo ZIP',
'Upd_Guide_Run_Validation' => '{auto} dopo il caricamento (è possibile rieseguirla con il pulsante {button}). Il sistema verifica: integrità dello ZIP, struttura e completezza del pacchetto, compatibilità della versione (i downgrade vengono rifiutati), versione PHP ed estensioni richieste, permessi dei file, spazio libero su disco, connessione al database, configurazione e che non sia in corso un altro aggiornamento.',
'Upd_Validation_Runs_Automatically' => 'La convalida viene eseguita automaticamente',
'Upd_Guide_Run_Review' => 'Esaminare il pannello {panel}. Il pulsante {button} appare solo quando tutti i controlli critici vengono superati. Se un controllo non riesce, il messaggio indica esattamente cosa correggere.',
'Upd_Guide_Run_Click' => 'Fare clic su {button} e confermare. Poi è sufficiente {keep} e seguire la barra di avanzamento. Il sistema esegue, nell\'ordine:',
'Upd_Keep_Page_Open' => 'mantenere aperta questa pagina',
'Upd_Guide_Phase_Backup' => '{label} — vengono creati e {verified} un dump completo del database, uno ZIP di tutti i file dell\'applicazione che l\'aggiornamento può modificare e una copia di {env}. I file caricati ({images}) e {storage} non vengono mai toccati da un aggiornamento, quindi non vengono archiviati. Se non è possibile creare un backup, l\'aggiornamento si interrompe qui e non viene modificato nulla.',
'Upd_Verified' => 'verificati',
'Upd_Guide_Phase_Prepare' => '{label} — la nuova versione viene estratta in un\'area di staging e convalidata di nuovo. L\'applicazione in produzione non è ancora stata toccata.',
'Upd_Guide_Phase_Maintenance' => '{label} — viene attivata la modalità manutenzione; i visitatori vedono una schermata cordiale "Torniamo subito".',
'Upd_Guide_Phase_Files' => '{label} — i nuovi file vengono sostituiti quasi istantaneamente; i vecchi file vengono conservati per il rollback. I percorsi protetti ({env}, {storage}, {images}) non vengono mai sostituiti.',
'Upd_Guide_Phase_Database' => '{label} — vengono eseguite le migrazioni, quindi vengono aggiornati permessi, traduzioni e modelli.',
'Upd_Guide_Phase_Cache' => '{label} — tutte le cache vengono svuotate e ricostruite.',
'Upd_Guide_Phase_Verify' => '{label} — i controlli di integrità confermano che la nuova versione si avvia, il database funziona, tutte le migrazioni sono state eseguite e la configurazione è valida.',
'Upd_Guide_Phase_Done' => '{label} — la modalità manutenzione viene disattivata e i file temporanei vengono eliminati.',
'Upd_Guide_Run_Success' => 'Quando appare {success}, fare clic su {reload} e aggiornare forzatamente il browser ({keys}) in modo che vengano caricate le nuove risorse del pannello di amministrazione.',
'Upd_Update_Successful_Short' => 'Aggiornamento riuscito',
'Upd_Guide_No_Internet' => 'Durante l\'aggiornamento non è necessaria alcuna connessione Internet — tutto proviene dallo ZIP caricato. Perdere la connessione o chiudere il browser NON compromette l\'aggiornamento: il server ricorda esattamente dove si è interrotto.',
'Upd_Guide_Wrong_Title' => '3. Se qualcosa va storto',
'Upd_Guide_Wrong_Rollback' => '{label} — se qualcosa non riesce dopo che i file hanno iniziato a cambiare (errore di estrazione, migrazione non riuscita, controllo di integrità fallito, disco pieno, …), il sistema ripristina automaticamente i file precedenti e il database dal backup verificato, disattiva la modalità manutenzione e segnala {message}. Si torna esattamente al punto di partenza.',
'Upd_Automatic_Rollback' => 'Rollback automatico',
'Upd_Failed_Previous_Restored' => 'Aggiornamento non riuscito — versione precedente ripristinata',
'Upd_Guide_Wrong_Interrupted' => '{label} (riavvio del server, timeout, browser chiuso, interruzione di corrente) — riaprendo questa pagina, un banner rosso offre due scelte sicure: {resume} (riprende dal passaggio esatto in cui si era interrotto) oppure {rollback} (ripristina la versione precedente dal backup).',
'Upd_Interrupted_Update' => 'Aggiornamento interrotto',
'Upd_Guide_Wrong_Unreachable' => '{label} — utilizzare la {console} autonoma all\'indirizzo {path}. Funziona anche quando il sito è in modalità manutenzione o le risorse del pannello di amministrazione sono danneggiate, e offre le stesse azioni Continua / Rollback. In fondo alla schermata di manutenzione è presente anche un discreto link "Accesso amministratore".',
'Upd_Admin_Unreachable' => 'Pannello di amministrazione irraggiungibile',
'Upd_Recovery_Console' => 'console di ripristino',
'Upd_Guide_Wrong_Locked_Out' => '{label} — mentre è in corso un aggiornamento, questa pagina mostra un {link}. Salvarlo se occorre rientrare (ad esempio dopo la scadenza della sessione); consente di superare la schermata di manutenzione per accedere di nuovo.',
'Upd_Locked_Out_Maintenance' => 'Bloccati dalla modalità manutenzione',
'Upd_Bypass_Link' => 'link di bypass',
'Upd_Guide_Wrong_Concurrent' => '{label} — vedrà {message} Può essere eseguito un solo aggiornamento alla volta.',
'Upd_Another_Admin_Updating' => 'Un altro amministratore tenta di aggiornare contemporaneamente',
'Upd_Guide_Backups_Title' => '4. Backup e ripristino',
'Upd_Guide_Backups_Created' => 'Ogni aggiornamento crea un backup {before} toccare qualsiasi cosa: tutti i file dell\'applicazione che l\'aggiornamento può sostituire, una copia di {env} e un dump completo del database. I file caricati e {storage} non vengono mai modificati da un aggiornamento e quindi non ne fanno parte — conservarne backup propri. I backup si trovano in {path} e non sono mai accessibili dal web.',
'Upd_Before' => 'prima di',
'Upd_Guide_Backups_Panel' => 'Il pannello {panel} nella scheda {tab} li elenca con data, versione e dimensione. Da lì è possibile {restore} qualsiasi backup completo (file + database — viene prima creata una copia di sicurezza del database corrente) oppure {delete} quelli vecchi.',
'Upd_Restore_Verb' => 'ripristinare',
'Upd_Delete_Verb' => 'eliminare',
'Upd_Guide_Backups_Retention' => 'Usare {keep} per scegliere quanti backup conservare; quelli più vecchi vengono rimossi automaticamente dopo ogni aggiornamento riuscito. L\'unico backup completo rimasto non può mai essere eliminato — resta sempre una via di ritorno.',
'Upd_Guide_Manual_Title' => '5. Aggiornamento manuale (metodo alternativo)',
'Upd_Guide_Manual_Text' => 'Se si preferisce aggiornare manualmente, o se il caricamento non può essere usato sul proprio server, seguire le istruzioni passo passo nella scheda {tab} di questa pagina.',
'Upd_Guide_Clear_Cache_First' => 'Se dopo un aggiornamento le pagine appaiono danneggiate o vuote, svuotare prima la cache del browser — è quasi sempre questa la causa.',
'Upd_Restore_Backup_Confirm' => 'Ripristinare questo backup? I file e il database correnti verranno sostituiti dal backup. Prima viene creata una copia di sicurezza del database corrente. (v{version} — {date})',
'Woo_Guide_Lead' => 'Come un negozio WooCommerce resta allineato con l\'ERP. Le righe cron qui sotto sono generate per questo server, quindi possono essere copiate direttamente su di esso.',
'Woo_Guide_Ways_Note' => 'A differenza di Shopify, WooCommerce non invia nulla all\'ERP di propria iniziativa — qui non c\'è un ricevitore di webhook, quindi tutto ciò che è {in} arriva secondo la pianificazione. Solo lo stock {out} può essere immediato.',
'Woo_In' => 'in entrata',
'Woo_Out' => 'in uscita',
'Woo_Guide_Both_Ways_Title' => 'Entrambe le modalità richiedono prima questo',
'Woo_Api_Keys' => 'Chiavi API',
'Woo_Guide_Api_Keys_Text' => '{path}, permesso {perm}. Copiare la consumer key e il secret nella scheda {settings}, insieme all\'URL del negozio — l\'indirizzo del sito senza barra finale, ad es. {example}.',
'Woo_Credentials_Saved' => 'credenziali salvate',
'Woo_Not_Configured_Yet' => 'non ancora configurato',
'Woo_Guide_Wp_App_Password_Title' => 'Password per le applicazioni di WordPress (facoltativa)',
'Woo_Guide_Wp_App_Password_Text' => 'Usata solo per le immagini dei prodotti. L\'API WooCommerce trasferisce prodotti, stock, categorie, marche, clienti e ordini; l\'API WordPress è quella che cerca nella Libreria media e carica un\'immagine non ancora presente.',
'Woo_Guide_Wp_App_Password_Note' => 'Usare un utente WordPress che possa gestire i media e creare la password in {path}. Lasciando vuoti entrambi i campi tutto si sincronizza comunque — viene saltato solo l\'allegato delle immagini.',
'Woo_Guide_Pick_Way_Title' => 'Poi scegliere come mantenere l\'allineamento',
'Woo_Right_Away' => 'Immediatamente',
'Woo_Stock_Live' => 'stock in tempo reale',
'Woo_Stock_Not_Live' => 'stock non in tempo reale',
'Woo_Guide_Realtime_Lead' => 'Una sola direzione: stock e prodotti in uscita dall\'ERP. Gli ordini e le modifiche ai prodotti effettuati in WooCommerce arrivano comunque secondo la pianificazione — vedere l\'altra scheda.',
'Woo_Push_Stock_On_Change' => 'Invia lo stock nel momento in cui cambia',
'Woo_Setting_People_Miss' => 'È l\'impostazione che molti trascurano',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Una vendita POS {not} a WooCommerce da sola. Se l\'opzione è disattivata, il negozio lo scopre solo alla successiva sincronizzazione dello stock — un\'ora, per impostazione predefinita — e in quell\'intervallo può vendere un\'unità già venduta alla cassa.',
'Woo_Does_Not' => 'non arriva',
'Woo_Guide_Tick_Instant' => 'Selezionare {option} nella scheda {settings}. Questa è l\'intera configurazione — nessun worker, nessun cron. Ogni vendita, reso, rettifica, trasferimento e acquisto ricevuto invia quindi un push dei soli prodotti interessati, subito dopo il salvataggio della vendita, e una vendita di venti righe costa un solo push, non venti. La cassa non lo attende mai.',
'Woo_Currently' => 'Attualmente:',
'Woo_Instant_On_Text' => 'attivo — stock inviato a ogni modifica',
'Woo_Instant_Off_Text' => 'disattivo — stock solo secondo la pianificazione',
'Woo_Guide_Instant_Note' => 'Vengono inviati solo i prodotti già collegati a WooCommerce — un prodotto mai sincronizzato non ha nulla da correggere nel negozio. I prodotti variabili passano attraverso il prodotto padre e un combo viene reinviato quando uno qualsiasi dei suoi componenti si muove. Le operazioni massive (eliminazione di un prodotto, reimpostazione di un magazzino) scrivono lo stock senza generare un evento: è uno dei motivi per mantenere anche la sincronizzazione oraria dello stock.',
'Woo_Push_Products_On_Save' => 'Invia i prodotti nel momento in cui vengono salvati',
'Woo_Guide_Tick_Auto_Products' => 'Selezionare {option} nella scheda {settings} e un prodotto creato, modificato o duplicato in Stocky viene inviato a WooCommerce subito dopo il salvataggio — dettagli, prezzo, varianti e immagini, poi il suo stock. Un nuovo prodotto viene creato subito nel negozio invece di attendere la sincronizzazione notturna dei prodotti.',
'Woo_On' => 'attivo',
'Woo_Off' => 'disattivo',
'Woo_Guide_Bulk_Imports_Note' => 'Le importazioni massive non vengono inviate una per una — eseguire una sincronizzazione dei prodotti dopo un\'importazione. Sincronizzare prima categorie e marche, in modo che un prodotto inviato finisca nella categoria corretta.',
'Woo_Nothing_Else_To_Install' => 'Nient\'altro da installare',
'Woo_Guide_Same_Process' => 'Nessun worker di coda, nessuna voce cron. Il push viene eseguito nello stesso processo che ha servito la vendita, {after} la risposta è stata restituita, quindi la cassa non attende mai WooCommerce. I push non si sovrappongono mai: le modifiche effettuate mentre uno è in corso lo attendono e vengono inviate subito dopo.',
'Woo_After' => 'dopo che',
'Woo_Guide_Shop_Stops_Answering' => 'Un negozio che smette di rispondere viene abbandonato dopo otto secondi e i push vengono sospesi per cinque minuti, così che ogni vendita non debba attenderlo di nuovo; le modifiche arrivate nel frattempo vengono inviate con il primo push dopo la pausa e la sincronizzazione oraria dello stock recupera comunque. Ogni pausa viene registrata nella scheda Log.',
'Woo_Guide_Artisan_Exception' => 'Un\'eccezione: una modifica dello stock effettuata da un comando artisan non ha una risposta dopo cui eseguire il push, quindi viene messa in coda su {queue}. Per inviare tempestivamente anche quelle, svuotare quella coda:',
'Woo_Cron_Line_Copied' => 'Riga cron copiata',
'Woo_Command_Copied' => 'Comando copiato',
'Woo_Guide_Not_Woo_Queue' => 'Volutamente non la coda {queue}: quella trasporta i batch del catalogo che durano ore, e un push immediato accodato dietro uno di essi non sarebbe immediato.',
'Woo_On_A_Schedule' => 'Secondo una pianificazione',
'Woo_Guide_Scheduled_Lead' => 'Tutto viene ricontrollato periodicamente, in entrambe le direzioni. È così che gli ordini raggiungono l\'ERP, che un catalogo viene pubblicato e che viene riparato tutto ciò che il percorso rapido ha mancato. Ogni job ha la propria voce cron, quindi si esegue solo ciò che si desidera.',
'Woo_Guide_Sync_Drains_Queue' => '{command} svuota la propria coda durante l\'esecuzione, quindi queste righe non richiedono un worker separato. Su Windows, usare l\'Utilità di pianificazione con il programma {program} e gli stessi argomenti, avviato in {path}.',
'Woo_Or_No_Cron' => 'Oppure nessun cron',
'Woo_Guide_No_Cron_Text' => 'Ogni scheda qui sincronizza su richiesta e una sincronizzazione manuale svuota i propri batch mentre la pagina è aperta — quindi un piccolo negozio può funzionare senza alcuna voce cron. Si perde però tutto ciò che accade quando nessuno controlla: gli ordini arrivano solo quando qualcuno preme il pulsante.',
'Woo_Commands_Worth_Knowing' => 'Comandi utili',
'Woo_Worth_Knowing' => 'Da sapere',
'Woo_Guide_Changing_Url_Clears' => 'Modificare l\'URL del negozio o le chiavi API cancella tutte le associazioni — prodotti, categorie, marche e clienti vengono tutti sincronizzati di nuovo con il nuovo negozio.',
'Woo_Guide_Keep_Skus' => 'Mantenere gli SKU coerenti tra Stocky e WooCommerce: è ciò che evita i duplicati e rende sicuro il ricollegamento.',
'Woo_Guide_Stock_Total' => 'Lo stock pubblicato su Woo è il {total}, non la cifra di un singolo magazzino.',
'Woo_Total_Across_Warehouses' => 'totale di tutti i magazzini',
'Woo_Guide_Full_Reference' => 'Il riferimento completo — ogni ambito, il comportamento della coda e un elenco per la risoluzione dei problemi — si trova in {file}.',
'Woo_Way_Covers' => 'Copre',
'Woo_Way_Covers_Realtime' => 'Solo lo stock in uscita dall\'ERP — una vendita POS, un reso, una rettifica, un acquisto ricevuto',
'Woo_Way_Covers_Scheduled' => 'Tutto, in entrambe le direzioni: ordini e modifiche ai prodotti in entrata, catalogo e stock in uscita',
'Woo_Way_Speed' => 'Velocità',
'Woo_Way_Seconds' => 'Secondi',
'Woo_Way_Speed_Scheduled' => 'Quella impostata nella voce cron (stock ogni ora, ordini ogni 15 min)',
'Woo_Way_Needs' => 'Requisiti',
'Woo_Way_Needs_Realtime' => 'Nulla — solo l\'impostazione',
'Woo_Way_Needs_Scheduled' => 'Una voce cron per job — oppure nulla, se si sincronizza manualmente',
'Woo_Way_Switched_On_At' => 'Si attiva in',
'Woo_Way_Cron_Entries_Below' => 'Le voci cron qui sotto',
'Woo_Cron_Orders' => 'Ordini ogni 15 minuti — solo quelli modificati dall\'ultima esecuzione.',
'Woo_Cron_Products_Pull' => 'Modifiche ai prodotti dal negozio, ogni notte alle 03:00.',
'Woo_Cron_Customers' => 'Clienti, ogni notte alle 03:30.',
'Woo_Cron_Stock' => 'Stock ogni ora — la rete di sicurezza sotto il push immediato, e l\'unica sincronizzazione dello stock in sua assenza.',
