'Woo_Wp_Username' => 'Nome utente WordPress',
'Woo_Wp_App_Password' => 'Password per le applicazioni di WordPress',
'Woo_Settings_Instant_Hint' => 'Una vendita, un reso o una rettifica invia un push dello stock dei soli prodotti interessati nell\'istante in cui viene salvato, così il negozio è corretto in pochi secondi invece che alla successiva sincronizzazione oraria dello stock. Nient\'altro da installare — il push viene eseguito dopo che la vendita ha ricevuto risposta, quindi la cassa non attende mai WooCommerce. Ulteriori dettagli nella scheda {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Se è disattivato, una vendita POS raggiunge WooCommerce solo alla successiva sincronizzazione dello stock — fino a un\'ora dopo.',
'Woo_Settings_Auto_Products_Hint' => 'Un prodotto creato, modificato o duplicato in Stocky viene inviato a WooCommerce subito dopo il salvataggio — dettagli, prezzo, varianti, immagini, poi il suo stock — invece di attendere una sincronizzazione dei prodotti. Le importazioni massive non vengono inviate; eseguire una sincronizzazione dei prodotti dopo un\'importazione.',
'Woo_Sync_Tuning' => 'Ottimizzazione della sincronizzazione',
'Woo_Sync_Tuning_Intro' => 'I valori predefiniti sono adatti alla maggior parte dei negozi. Modificarli solo se la sincronizzazione è lenta o va in timeout sul proprio hosting. Ogni valore è limitato a un intervallo sicuro e svuotare un campo ne ripristina il valore predefinito.',
'Woo_Setting_This_Up' => 'Configurazione',
'Woo_Setting_This_Up_Text' => 'Come ottenere le chiavi API, a cosa serve la password per le applicazioni di WordPress, le voci cron per le sincronizzazioni pianificate e come far arrivare lo stock al negozio nel momento in cui cambia — tutto questo, con le righe cron di questo server pronte da copiare, si trova nella scheda Guida. Un\'unica copia, così non può discostarsi da ciò che il modulo fa realmente.',
