'Telegram_G_A_Title' => 'Immediatamente — nulla da installare',
'Telegram_G_A_Body' => 'Una vendita, un acquisto, un pagamento o una spesa salvati in Stocky — al POS o nel pannello di amministrazione — vengono inviati a Telegram {after} essere stati salvati, nella stessa richiesta. Nessuna voce cron, nessun worker di coda, e il cassiere non attende mai Telegram: la vendita ha già ricevuto risposta quando il messaggio parte.',
'Telegram_G_Right_After' => 'subito dopo',
'Telegram_G_B_Title' => 'La voce cron — per i nuovi tentativi e gli eventi in background',
'Telegram_G_B_Body' => 'Due tipi di messaggi attendono invece nella coda di Telegram: un invio non riuscito (Telegram momentaneamente irraggiungibile), che viene ritentato fino ad altre tre volte nei minuti successivi; e gli eventi generati al di fuori del pannello di amministrazione — ordini importati da WooCommerce o Shopify, comandi artisan. Questa voce cron li invia, e nient\'altro:',
'Telegram_G_Cron_Note' => 'Ogni minuto va bene: un\'esecuzione senza nulla in attesa termina subito. Su cPanel va inserita in {cronJobs} — usare il percorso completo di PHP 8.2+ se {php} è più vecchio. Su Windows, usare l\'Utilità di pianificazione con il programma {program}, gli argomenti {args}, avviato in {path}.',
