'Salla_Guide_4' => 'Nella pagina Webhooks dell\'app: scegli la strategia di sicurezza {signature}, copia il relativo secret nel campo Webhook Secret qui, imposta l\'URL webhook mostrato nella scheda Connessione e iscriviti almeno a {e1}, {e2}, {e3}, {e4}, {e5} e {e6}.',
'Salla_Guide_5' => 'Fai clic su {connect} e approva l\'app nel tuo negozio. (Le app in Easy Mode si connettono invece automaticamente tramite il webhook {webhook}.)',
