'Presta_Saved_Paste_New_Key' => 'Salvata — incolla una nuova chiave per sostituirla',
'Presta_From_Menu' => 'Da {menu}',
'Presta_Webservice_Key_Help' => 'Abilita il webservice in PrestaShop ({menu}), crea una chiave con permessi su products, stock_availables, orders e customers e incollala qui. Memorizzata in sola scrittura.',
'Presta_Shop_Language_Id' => 'ID lingua del negozio',
'Presta_Shop_Language_Help' => 'ID lingua usato per i nomi dei prodotti durante l\'invio (1 = la prima lingua del negozio).',
'Presta_Push_Products_Desc' => 'Crea su PrestaShop i prodotti semplici mancanti (con il loro stock attuale). I prodotti già collegati e i prodotti con varianti vengono ignorati — continua a modificare i dettagli dei prodotti in PrestaShop oppure esegui un\'importazione per aggiornare la copia locale.',
'Presta_Pull_Products_Desc' => 'Importa i prodotti PrestaShop, abbinando quelli esistenti tramite riferimento (SKU) e creando gli altri. Le combinazioni vengono importate come il relativo prodotto principale.',
'Presta_Reset_Product_Confirm' => 'Reimpostare i collegamenti dei prodotti? Lo storico ordini mantiene i propri collegamenti.',
'Presta_Push_Stock_Desc' => 'Aggiorna lo stock del negozio (stock_availables) per ogni prodotto collegato.',
'Presta_Pull_Orders_Desc' => 'Importa gli ordini del negozio come vendite (riferimenti come {ref}), dal più recente. Gli ordini già importati e quelli annullati vengono ignorati, quindi importare regolarmente è sicuro. PrestaShop non dispone di webhook — esegui questa operazione dopo i periodi di maggiore attività.',
'Presta_Guide_1' => 'Nel back office di PrestaShop, apri {menu} e abilita il webservice.',
'Presta_Guide_2' => 'Aggiungi una nuova chiave, concedendo {rw} su {products} e {stock} e {view} su {orders} e {customers}.',
'Presta_Guide_3' => 'Incolla l\'URL del negozio e la chiave nella scheda Connessione, salva ed esegui {test}.',
'Presta_Guide_4' => 'Importa prima i prodotti se il negozio ha già un catalogo (abbinamento per riferimento/SKU); invia per creare i prodotti semplici mancanti.',
'Presta_Guide_5' => 'Invia lo stock ogni volta che le quantità cambiano e importa regolarmente gli ordini — PrestaShop non dispone di webhook, quindi gli ordini arrivano solo quando li importi.',
'Presta_Identity_Title' => 'L\'identità del prodotto è il riferimento (SKU)',
'Presta_Identity_Desc' => 'Il codice prodotto di Stocky viene abbinato al riferimento di PrestaShop. Mantieni i riferimenti coerenti su entrambi i lati; le combinazioni (varianti) vengono abbinate negli ordini tramite riferimento ma non vengono inviate in questa versione.',
'Xero_Hero_Title' => 'Sincronizzazione contabile Xero',
