'Xero_Push_Customers_To' => 'Invia clienti a {name}',
'Xero_Push_Customers_Desc' => 'Crea o aggiorna un contatto Xero per ogni cliente. Un cliente il cui nome esiste già in Xero viene collegato a quel contatto.',
'Xero_Push_Customers' => 'Invia clienti',
'Xero_Push_Sales_Invoices' => 'Invia vendite come fatture',
'Xero_Push_Invoices_Desc' => 'Crea una fattura AUTHORISED per vendita (numero fattura = il Riferimento della vendita), con le righe articolo della vendita più le righe di spedizione, sconto e imposta, in modo che il totale Xero corrisponda al totale della vendita. Le vendite già presenti in Xero vengono ignorate — le fatture non vengono mai modificate. I contatti mancanti vengono creati al momento.',
'Xero_Push_Invoices' => 'Invia fatture',
'Xero_Reset_Contact_Confirm' => 'Reimpostare i collegamenti dei contatti? Il prossimo invio li ricollegherà o li ricreerà.',
