'Xero_Guide_1' => 'Crea una {webApp} su {link} ({menu}).',
'Xero_Guide_2' => 'Registra l\'URI di reindirizzamento mostrato nella scheda Connessione.',
'Xero_Guide_3' => 'Copia il {clientId} dell\'app e genera un {clientSecret}; incollali entrambi qui e salva.',
'Xero_Guide_4' => 'Fai clic su {connect}, accedi e scegli l\'organizzazione da connettere.',
'Xero_Guide_5' => 'Controlla i codici dei conti: il conto vendite riceve le righe delle fatture; imposta un codice di conto bancario se le vendite pagate devono registrare anche i pagamenti.',
'Xero_Guide_6' => 'Invia prima i clienti, poi le fatture. I numeri delle fatture sono i Riferimenti delle vendite, quindi i duplicati vengono rifiutati da Xero anche se i collegamenti vengono reimpostati.',
'Xero_Amounts_Title' => 'Gli importi vengono inviati IVA inclusa così come sono',
'Xero_Amounts_Desc' => 'Le fatture usano righe NoTax che rispecchiano esattamente la vendita (articoli + spedizione − sconto + imposta), quindi i totali Xero corrispondono sempre ai totali Stocky. Il tuo commercialista può riassegnare le righe di imposta e spedizione ai conti appropriati all\'interno di Xero.',
'Xero_Org_Connected' => 'Organizzazione Xero connessa.',
'Jumia_Hero_Title' => 'Sincronizzazione marketplace Jumia',
'Jumia_Hero_Desc' => 'Invia prezzi e stock alle tue inserzioni Jumia Seller Center e importa gli ordini del marketplace come vendite.',
'Jumia_Api_Url_Label' => 'URL API (endpoint Seller Center del tuo paese)',
'Jumia_Account_Email' => 'Email dell\'account (User ID)',
'Jumia_Api_Key' => 'Chiave API',
'Jumia_Prices_Stock' => 'Prezzi e stock',
'Jumia_Push_Prices_Stock_Title' => 'Invia prezzi e stock a Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Invia il prezzo e la quantità attuali per ogni prodotto (e variante) con uno SKU corrispondente al {sku} dell\'inserzione Jumia. Gli aggiornamenti vengono inviati come feed Seller Center e applicati in modo asincrono — l\'ID del feed viene registrato nella scheda Log e i rifiuti dei singoli articoli compaiono nella schermata di stato dei feed di Seller Center.',
'Jumia_Push_Prices_Stock' => 'Invia prezzi e stock',
'Jumia_Pull_Orders_Desc' => 'Importa gli ordini del marketplace come vendite (riferimenti come {ref}), abbinati ai tuoi prodotti tramite Seller SKU. Gli ordini già importati e quelli annullati vengono ignorati, quindi importare regolarmente è sicuro. I pagamenti vengono segnati come pagati solo per gli ordini consegnati (Jumia è prevalentemente in contrassegno).',
'Jumia_Guide_1' => 'In Jumia {sellerCenter}, apri {menu} e genera una chiave API.',
'Jumia_Guide_2' => 'Inserisci l\'URL API del tuo paese (es. {ng} per la Nigeria, {ke} per il Kenya, {eg} per l\'Egitto), l\'email del tuo account Seller Center e la chiave — quindi esegui {test}.',
'Jumia_Guide_3' => 'Assicurati che il {sku} di ogni inserzione Jumia corrisponda al codice prodotto Stocky — è l\'identità usata sia per l\'invio dello stock sia per l\'abbinamento degli ordini.',
'Jumia_Guide_4' => 'Invia prezzi e stock dopo le modifiche all\'inventario; importa regolarmente gli ordini (Jumia non dispone di webhook in questa API).',
'Jumia_Guide_5' => 'La creazione di nuove inserzioni resta in Seller Center — Jumia richiede attributi specifici per categoria e una revisione delle immagini che solo il loro portale gestisce bene.',
'Mailchimp_Hero_Title' => 'Sincronizzazione audience Mailchimp',
'Mailchimp_Hero_Desc' => 'Mantieni un\'audience Mailchimp popolata con i tuoi clienti, così da poter eseguire campagne email sulla tua reale base clienti.',
'Mailchimp_Account_Audience' => 'Account e audience',
'Mailchimp_Api_Key_Ph' => 'es. {example} ({menu})',
'Mailchimp_Audience_Option' => '{name} ({n} membri)',
'Mailchimp_Load_Audiences_Ph' => 'Carica le audience per sceglierne una',
'Mailchimp_Load_Audiences' => 'Carica audience',
'Mailchimp_Double_Optin_Label' => 'Double opt-in — i nuovi membri ricevono un\'email di conferma prima di iscriversi',
'Mailchimp_Double_Optin_Hint' => '(consigliato per il GDPR)',
'Mailchimp_Auto_Sync_Customers' => 'Sincronizza automaticamente i nuovi clienti man mano che vengono creati',
'Mailchimp_With_Email' => 'Con un\'email',
'Mailchimp_Push_Desc' => 'Inserisce o aggiorna nell\'audience selezionata ogni cliente che ha un indirizzo email (nome e telefono inclusi). I membri esistenti mantengono il proprio stato di iscrizione — nessuno che si sia disiscritto viene reiscritto. I clienti senza email vengono esclusi.',
'Mailchimp_Double_Optin_Off_Title' => 'Il double opt-in è disattivato',
'Mailchimp_Double_Optin_Off_Desc' => 'I nuovi membri verranno aggiunti come iscritti senza un\'email di conferma. Fallo solo per i clienti che hanno già acconsentito a ricevere comunicazioni di marketing.',
'Mailchimp_Guide_1' => 'In Mailchimp, apri {menu} e crea una chiave (termina con {suffix} — quel suffisso è il tuo datacenter).',
'Mailchimp_Guide_2' => 'Incolla qui la chiave, salva, quindi fai clic su {load} e scegli l\'audience da popolare.',
'Mailchimp_Guide_3' => 'Lascia attivo il {doubleOptIn} a meno che i tuoi clienti non abbiano già acconsentito alle email di marketing.',
'Mailchimp_Double_Optin_Term' => 'double opt-in',
'Mailchimp_Guide_4' => 'Esegui {push} per il popolamento iniziale; attiva la {autoSync} in modo che i nuovi clienti vengano aggiunti automaticamente.',
'Mailchimp_Auto_Sync_Term' => 'sincronizzazione automatica',
'Mailchimp_Consent_Title' => 'Il consenso è importante',
'Mailchimp_Consent_Desc' => 'Inviare email a persone che non hanno mai acconsentito al marketing può violare GDPR/CAN-SPAM e causare la sospensione del tuo account Mailchimp. Il double opt-in sposta la conferma su Mailchimp — l\'impostazione predefinita sicura.',
'Mailchimp_No_Audiences' => 'Nessuna audience trovata in questo account.',
