'Shopify_G_Both_Need' => 'Entrambe le modalità richiedono prima questo',
'Shopify_G_Credentials' => 'Credenziali Shopify',
'Shopify_G_Cred_Intro' => 'Da gennaio 2026 Shopify non crea più app personalizzate all\'interno dell\'amministrazione, quindi esistono due tipi di connessione:',
'Shopify_G_Cred_DevDash' => '{app} (qualsiasi negozio connesso oggi) — {path}. Concedi gli scope Admin API per ciò che questo negozio sincronizza, installa l\'app sul negozio, quindi copia {clientId} e {clientSecret} dalla pagina Impostazioni dell\'app in {where}. L\'ERP li scambia autonomamente con un token di accesso e lo rinnova prima della scadenza ogni 24 ore. Il client secret firma anche i webhook, quindi non serve altro. L\'app e il negozio devono trovarsi nella stessa organizzazione Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'App Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (creata nell\'amministrazione prima del 2026) — continua a funzionare invariata con il suo {token} ({prefix}) e la sua {secret} come secret di firma dei webhook. Non è lo stesso valore del token, e invertirli è il motivo più comune per cui i webhook vengono rifiutati.',
'Shopify_G_Legacy_App' => 'App personalizzata legacy',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'memorizzato',
'Shopify_G_Missing_Refused' => 'mancante — le consegne verranno rifiutate',
'Shopify_G_Where_Data_Desc' => '{path} Il magazzino ERP il cui stock viene venduto da questo negozio e la sede Shopify in cui tale stock viene scritto. La sincronizzazione dell\'inventario e l\'importazione degli ordini rifiutano entrambe di essere eseguite senza di essi.',
'Shopify_G_Currently' => 'Attualmente: magazzino {warehouse}, sede {location}',
'Shopify_G_Not_Set_Lower' => 'non impostato',
'Shopify_G_Ready' => 'pronto',
'Shopify_G_Incomplete' => 'incompleto',
'Shopify_G_Manual_Syncs' => 'Sincronizzazioni avviate manualmente',
'Shopify_G_Manual_Desc' => 'Una sincronizzazione avviata dal {centre} risponde subito e viene eseguita in background, in brevi blocchi che riprendono ciascuno da dove si era fermato il precedente. Un catalogo di grandi dimensioni non viene mai interrotto a metà da un hosting che chiude le richieste web lunghe (LiteSpeed, nginx, un bilanciatore di carico) e chiudere la pagina non la interrompe. Il worker necessario è un\'ulteriore riga cron:',
'Shopify_G_Cron_Copied' => 'Riga cron copiata',
'Shopify_G_Manual_Note' => 'Senza di essa una sincronizzazione viene comunque completata, ma solo finché la pagina Sync Centre resta aperta: quando nessun worker prende in carico un\'esecuzione entro pochi secondi, la pagina la porta avanti da sé, una breve richiesta alla volta. Su Windows usa l\'Utilità di pianificazione ogni minuto: programma {program}, argomenti {args}, avvio in {dir}.',
'Shopify_G_Then_Pick' => 'Poi scegli come mantenere l\'allineamento',
'Shopify_G_Right_Away' => 'Immediatamente',
'Shopify_G_Stock_Live' => 'stock in tempo reale',
'Shopify_G_Stock_Not_Live' => 'stock non in tempo reale',
'Shopify_G_Realtime_Lead' => 'Ogni modifica viene inviata nel momento in cui avviene, in pochi secondi. Due metà, con interruttori separati: i {webhooks} portano dentro gli eventi del negozio e l\'{push} invia lo stock all\'esterno.',
'Shopify_G_Webhooks_Lower' => 'webhook',
'Shopify_G_Instant_Push_Lower' => 'invio immediato dello stock',
'Shopify_G_Webhooks_In' => 'Webhook — dal negozio all\'ERP',
'Shopify_G_Webhooks_Desc' => 'Ordini, cambi di stato degli ordini e modifiche a prodotti, clienti e stock effettuate in Shopify. Apri il negozio e premi {button} nella sua {tab} — puoi premerlo due volte senza problemi. Shopify invia a:',
'Shopify_G_Webhooks_Tab' => 'scheda Webhook',
'Shopify_G_Webhooks_Note' => 'L\'indirizzo deve essere raggiungibile da internet tramite HTTPS — Shopify non consegna a {localhost} o a un dominio {test}. Ogni consegna viene registrata una sola volta, quindi i nuovi tentativi di Shopify non possono creare un ordine duplicato, e una consegna non riuscita può essere rieseguita. Le consegne vengono rifiutate finché il secret di firma del passaggio 1 non viene memorizzato.',
'Shopify_G_Instant_Out' => 'Invio immediato dello stock — dall\'ERP al negozio',
'Shopify_G_Setting_Missed' => 'Questa è l\'impostazione che molti trascurano',
'Shopify_G_Pos_Not_Auto' => 'Una vendita POS {not} arriva a Shopify da sola. Se l\'opzione è disattivata, il negozio lo scopre solo al successivo passaggio di invio dell\'inventario e, in quell\'intervallo, può vendere un\'unità che hai già venduto alla cassa.',
'Shopify_G_Not' => 'non',
'Shopify_G_Tick_Push' => 'Seleziona {setting} in {where}. Questa è tutta la configurazione: nessun worker, nessun cron. Ogni vendita, reso e rettifica invia quindi un aggiornamento solo di quei prodotti, subito dopo il salvataggio della vendita, e una vendita di venti righe costa un solo invio, non venti. La cassa non lo attende mai.',
'Shopify_G_This_Store' => 'Questo negozio:',
'Shopify_G_Push_On' => 'attivo: stock inviato a ogni modifica',
'Shopify_G_Push_Off' => 'disattivo: stock solo secondo la pianificazione',
'Shopify_G_Push_Note' => 'Vengono inviati solo i prodotti che hanno già una mappatura Shopify e solo i movimenti nel magazzino di questo negozio. Le operazioni massive, come l\'eliminazione di un prodotto o l\'azzeramento di un magazzino, scrivono lo stock senza generare un evento: è uno dei motivi per mantenere anche il passaggio pianificato dell\'inventario.',
'Shopify_G_Nothing_Install' => 'Nient\'altro da installare',
'Shopify_G_No_Worker_Note' => 'Nessuna delle due parti richiede un queue worker o una voce cron. Un webhook in arrivo viene gestito nella richiesta effettuata da Shopify; un invio di stock in uscita viene eseguito nello stesso processo che ha servito la vendita, {after} la risposta è stata restituita: così la cassa non attende mai Shopify, e un negozio che smette di rispondere viene abbandonato dopo dieci secondi e lasciato al successivo invio pianificato dell\'inventario.',
'Shopify_G_After' => 'dopo che',
'Shopify_G_Artisan_Note' => 'Un\'eccezione: una modifica di stock effettuata da un comando artisan non ha una risposta dopo cui eseguirsi, quindi viene accodata su {queue}. Se vuoi che anche queste vengano inviate tempestivamente, svuota quella coda:',
'Shopify_G_On_Schedule' => 'Pianificato',
'Shopify_G_On_Lower' => 'attivo',
'Shopify_G_Off_Lower' => 'disattivo',
'Shopify_G_Scheduled_Lead' => 'Tutto viene ricontrollato periodicamente, in entrambe le direzioni. È più lento del tempo reale, ma è ciò che invia lo stock ai negozi che non usano l\'invio istantaneo, che recupera un webhook perso ed è l\'unico modo per trasferire un intero catalogo.',
'Shopify_G_Cron_Entry' => 'La voce cron',
'Shopify_G_Cron_Entry_Desc' => 'Senza di essa non viene eseguito nulla di pianificato. Una sola riga, solo per questo modulo: aggiungila accanto a qualsiasi altra cosa tu abbia scelto di pianificare:',
'Shopify_G_Cron_Note' => 'Ogni cinque minuti è la risoluzione più fine utilizzabile da un piano, perché cinque minuti è l\'intervallo minimo di un passaggio. Una voce meno frequente diventa semplicemente il limite minimo: con {example}, un passaggio impostato a 5 minuti viene eseguito ogni 15. Su Windows usa l\'Utilità di pianificazione: programma {program}, argomenti {args}, avvio in {dir}.',
'Shopify_G_Switch_On_Plan' => 'Attivala e scegli il piano',
'Shopify_G_Plan_Desc' => '{where} L\'interruttore decide se il cron può agire; il piano decide cosa fa. Un {step} è un\'entità in una direzione con un proprio intervallo: {first}, {second}. L\'intervallo predefinito viene usato da ogni passaggio che lascia vuoto il proprio campo.',
'Shopify_G_Step_Lower' => 'passaggio',
'Shopify_G_Plan_Note' => 'Se lasci il piano vuoto, il negozio importa gli ordini e invia lo stock all\'intervallo predefinito, ed è ciò che serve alla maggior parte dei negozi. Gli ordini sono solo in importazione: è su Shopify che un cliente li effettua.',
'Shopify_G_Schedule_On' => 'pianificazione attiva',
'Shopify_G_Schedule_Off' => 'pianificazione disattiva: solo manuale',
'Shopify_G_When_Step_Runs' => 'Quando viene eseguito effettivamente un passaggio',
'Shopify_G_When_Note' => 'Un passaggio è da eseguire quando lo stesso passaggio è stato {started} l\'ultima volta da più tempo del suo intervallo, secondo la cronologia delle esecuzioni. Quindi una sincronizzazione avviata manualmente rinvia la successiva automatica, e un passaggio che continua a fallire viene ritentato secondo il suo intervallo anziché a ogni ciclo. La Panoramica del negozio mostra per ogni passaggio l\'ultima esecuzione, la prossima scadenza e il motivo del blocco, se presente. Esegui manualmente il primo invio del catalogo, prima con {dryRun}, prima di pianificarlo.',
'Shopify_G_Started_Lower' => 'avviato',
'Shopify_G_Where_Setting' => 'Dove si trova ogni impostazione',
'Shopify_G_Where_Setting_Note' => 'Si trovano tutte in un negozio esistente: {path}, quindi la matita (oppure {edit} nella pagina del negozio).',
'Shopify_G_Product_Images' => 'Immagini dei prodotti',
'Shopify_G_Img_1' => 'Le immagini vengono inviate con il prodotto durante un {push}: prima l\'immagine principale, poi la galleria, poi una per ogni variante che ne ha una propria, fino a cinquanta.',
'Shopify_G_Products_Push' => 'invio prodotti',
'Shopify_G_Img_2' => 'L\'immagine di una variante viene caricata con il prodotto e poi {assigned}, che è il modo in cui Shopify la gestisce: una variante punta a una delle immagini del prodotto. Una variante che riutilizza l\'immagine principale non la carica due volte.',
'Shopify_G_Assigned' => 'assegnata a quella variante',
'Shopify_G_Img_3' => 'Un\'immagine salvata come file viene {uploaded} su Shopify, non collegata, quindi funziona anche quando questa installazione non è raggiungibile da Internet. Un\'immagine aggiunta come link incollato viene passata a Shopify come URL, che deve essere pubblicamente raggiungibile.',
'Shopify_G_Uploaded' => 'caricata',
'Shopify_G_Img_4' => 'Vengono reinviate solo quando cambiano effettivamente: un invio che modifica solo un prezzo lascia invariate le immagini del negozio, perché inviarle sostituisce l\'intero set.',
'Shopify_G_Img_5' => 'Rimuovere un\'immagine nell\'ERP {not} la elimina in Shopify. Eliminala anche lì, altrimenti il negozio continuerà a mostrarla.',
'Shopify_G_Commands' => 'Comandi utili',
'Shopify_G_Command_Copied' => 'Comando copiato',
'Shopify_G_Foot' => 'Ogni sincronizzazione scrive in {logs}, e la Panoramica di ogni negozio mostra quando ogni passaggio è stato eseguito l\'ultima volta, quando è la prossima scadenza e cosa lo blocca, se qualcosa lo blocca. È il primo posto da controllare quando una sincronizzazione non ha fatto ciò che ti aspettavi.',
'Shopify_G_Covers' => 'Copre',
'Shopify_G_Covers_Rt' => 'Ordini e modifiche effettuati in Shopify; stock in uscita dall\'ERP (una vendita POS, un reso, una rettifica)',
'Shopify_G_Covers_Sch' => 'Tutto, in entrambe le direzioni, inclusi gli invii del catalogo e tutto ciò che il percorso rapido ha perso',
'Shopify_G_Speed' => 'Velocità',
'Shopify_G_Speed_Rt' => 'Secondi',
'Shopify_G_Speed_Sch' => 'L\'intervallo del passaggio (da 5 minuti a 7 giorni)',
'Shopify_G_Needs' => 'Requisiti',
'Shopify_G_Needs_Rt' => 'Un indirizzo HTTPS pubblico e la chiave di firma per i webhook in arrivo. Lo stock in uscita non richiede nulla',
'Shopify_G_Needs_Sch' => 'Una voce cron che esegue {cmd}',
'Shopify_G_Switched_On_At' => 'Attivato in',
'Shopify_G_On_Sch' => '{path}, più il piano',
'Shopify_G_Scope_Orders' => '{scope} ({extra} per ordini più vecchi di 60 giorni)',
'Shopify_G_Admin_Scopes' => 'Ambiti Admin API',
