'Shopify_G_Set_Credentials' => 'Client ID + secret o token di accesso, chiave di firma, versione API',
'Shopify_G_Set_Credentials_What' => 'Le credenziali dell\'app Shopify (Dev Dashboard o app personalizzata legacy).',
'Shopify_G_Set_Targets' => 'Magazzino ERP, sede Shopify',
'Shopify_G_Set_Targets_What' => 'Quale stock vende questo negozio e dove vengono registrati gli ordini.',
'Shopify_G_Set_Price_What' => 'Prezzo al dettaglio, all\'ingrosso o minimo.',
'Shopify_G_Set_Create_Missing' => 'Crea prodotti / clienti mancanti',
'Shopify_G_Set_Create_Missing_What' => 'Se un\'importazione può creare record ERP che non riesce ad abbinare.',
'Shopify_G_Set_Entities' => 'Quali entità vengono sincronizzate',
'Shopify_G_Set_Entities_What' => 'Disattivato qui significa disattivato ovunque: manuale, pianificato e webhook.',
'Shopify_G_Set_Scheduler_What' => 'L\'interruttore della pianificazione.',
'Shopify_G_Set_Push_What' => 'Invio istantaneo dello stock, accodato a ogni vendita o rettifica.',
'Shopify_G_Set_Plan' => 'Intervallo predefinito e piano dei passaggi',
'Shopify_G_Set_Plan_What' => 'Cosa viene eseguito automaticamente, in quale direzione e con quale frequenza.',
'Shopify_G_Cmd_List' => 'Tutti i negozi: cosa verrebbe eseguito e quando. Non modifica nulla.',
'Shopify_G_Cmd_Force' => 'L\'intero piano di un negozio subito, ignorando l\'orario.',
'Shopify_G_Cmd_First_Push' => 'Primo invio del catalogo: solo i prodotti non ancora collegati.',
'Shopify_G_Cmd_Backfill' => 'Recupera gli ordini a partire da una data.',
'Shopify_G_Cmd_Dry' => 'Esegue la simulazione e genera un resoconto, senza scrivere nulla da nessuna parte.',
