'StoreAdm_NA' => 'N/D',
'StoreAdm_Eg' => 'es. {example}',
'StoreAdm_Stock_Required_Available' => '{name}: Richiesti {need} — Disponibili {have}',
'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash e SSLCommerz sono usati SOLO dal checkout del NEGOZIO ONLINE.',
'StoreAdm_PG_Intro_Desc' => 'Le chiavi Stripe sono condivise globalmente (l\'amministrazione e il negozio online usano la stessa integrazione Stripe). Ogni scheda attiva o disattiva il relativo metodo per il checkout del negozio online; Pagamenti offline contiene i metodi pagati al di fuori del sistema.',
'StoreAdm_PG_Used_By_Store_Only' => 'Usato solo dal checkout del negozio online',
'StoreAdm_PG_Gw_Key' => 'Chiave {gw}',
'StoreAdm_PG_Gw_Secret' => 'Secret {gw}',
'StoreAdm_PG_Cards_Off' => 'I pagamenti con carta sono disattivati',
'StoreAdm_PG_Cards_Off_Desc' => 'Le tue chiavi vengono conservate: il checkout del negozio online smette semplicemente di offrire l\'opzione carta finché non la riattivi.',
'StoreAdm_PG_No_Stripe_Key' => 'Nessuna chiave Stripe salvata',
'StoreAdm_PG_No_Stripe_Key_Desc' => 'Inserisci la chiave e il secret Stripe per iniziare ad accettare pagamenti con carta nel negozio online.',
'StoreAdm_PG_Gw_Client_Id' => 'Client ID {gw}',
'StoreAdm_PG_Gw_Client_Secret' => 'Client Secret {gw}',
'StoreAdm_PG_Sandbox' => 'Sandbox (modalità di test)',
'StoreAdm_PG_Sandbox_Paypal_Hint' => 'Se ATTIVO usa {sandbox} con credenziali sandbox; DISATTIVALO per addebitare conti reali su {live}.',
'StoreAdm_PG_Gw_Webhook_Id_Opt' => 'Webhook ID {gw} (facoltativo)',
'StoreAdm_PG_Paypal_Webhook_Hint' => 'Sistema di riserva per i pagamenti il cui reindirizzamento del browser non arriva mai, oltre a rimborsi e chargeback. Registra un webhook su {site} che punti all\'URL qui sotto (eventi: {events}) e incolla qui il relativo Webhook ID.',
'StoreAdm_PG_Webhook_Url' => 'URL del webhook:',
'StoreAdm_PG_Gw_Disabled' => '{gw} è disattivato',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Attiva PayPal e inserisci il Client ID e il Secret della tua app REST (da {site}) per consentire ai clienti di pagare con PayPal al checkout del negozio online.',
'StoreAdm_PG_Gw_Public_Key' => 'Chiave pubblica {gw}',
'StoreAdm_PG_Gw_Secret_Key' => 'Chiave segreta {gw}',
'StoreAdm_PG_Paystack_Test_Live' => 'La modalità test o live è determinata dalla coppia di chiavi: le chiavi {test} funzionano in modalità test, le chiavi {live} addebitano carte reali; non esiste un interruttore sandbox separato.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'URL del webhook (sistema di riserva facoltativo: impostalo in Settings → API Keys & Webhooks nella dashboard di Paystack; le richieste vengono verificate tramite HMAC con la tua chiave segreta):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Attiva Paystack e inserisci le chiavi pubblica e segreta (da {site} → Settings → API Keys) per accettare carte, bonifici bancari e mobile money al checkout del negozio online.',
'StoreAdm_PG_Secret_Hash_Opt' => 'Secret Hash (webhook, facoltativo)',
'StoreAdm_PG_Flutterwave_Hash_Hint' => 'Il Secret Hash impostato in Settings → Webhooks nella dashboard di Flutterwave; i webhook in arrivo vengono rifiutati se la loro intestazione {header} non corrisponde.',
'StoreAdm_PG_Flutterwave_Info' => 'Usa l\'API Flutterwave v3 con chiavi classiche. La modalità test o live è determinata dalla coppia di chiavi ({keys} contro chiavi live); non esiste un interruttore sandbox separato. La valuta del negozio deve essere abilitata sul tuo account Flutterwave.',
'StoreAdm_PG_Flutterwave_Webhook_Url' => 'URL del webhook (sistema di riserva facoltativo: impostalo insieme al Secret Hash qui sopra nella dashboard di Flutterwave):',
'StoreAdm_PG_Flutterwave_Disabled_Desc' => 'Attiva Flutterwave e inserisci le chiavi pubblica e segreta v3 (da {site} → Settings → API) per accettare carte, mobile money e bonifici bancari al checkout del negozio online.',
'StoreAdm_PG_Gw_Key_Id' => 'Key ID {gw}',
'StoreAdm_PG_Gw_Key_Secret' => 'Key Secret {gw}',
'StoreAdm_PG_Webhook_Secret_Opt' => 'Webhook Secret (facoltativo)',
'StoreAdm_PG_Razorpay_Secret_Hint' => 'Il secret definito durante la creazione del webhook nella dashboard di Razorpay; gli eventi in arrivo vengono verificati tramite HMAC con esso e altrimenti rifiutati.',
'StoreAdm_PG_Razorpay_Info' => 'Usa Razorpay Payment Links (carte, UPI, netbanking, wallet). La modalità test o live è determinata dalla coppia di chiavi ({keys}); non esiste un interruttore sandbox separato.',
'StoreAdm_PG_Razorpay_Webhook_Url' => 'URL del webhook (sistema di riserva facoltativo: registralo con il secret qui sopra in Settings → Webhooks; eventi: {events}):',
'StoreAdm_PG_Razorpay_Disabled_Desc' => 'Attiva Razorpay e inserisci Key ID e Key Secret (da {site} → Settings → API Keys) per accettare carte, UPI, netbanking e wallet al checkout del negozio online.',
'StoreAdm_PG_Gw_App_Key' => 'App Key {gw}',
'StoreAdm_PG_Gw_App_Secret' => 'App Secret {gw}',
'StoreAdm_PG_Gw_Username' => 'Nome utente {gw}',
'StoreAdm_PG_Gw_Password' => 'Password {gw}',
'StoreAdm_PG_Sandbox_Bkash_Hint' => 'Se ATTIVO usa {sandbox} con le tue credenziali sandbox; DISATTIVALO per addebitare conti bKash reali su {live}.',
'StoreAdm_PG_Bkash_Info' => 'Usa bKash Tokenized Checkout (credenziali commerciante dal portale commercianti bKash). bKash addebita solo in BDT: l\'opzione viene offerta al checkout solo quando la valuta attiva del negozio è BDT.',
'StoreAdm_PG_Bkash_Disabled_Desc' => 'Attiva bKash e inserisci App Key, App Secret, nome utente e password del Tokenized Checkout (dal portale commercianti bKash) per consentire ai clienti di pagare con bKash al checkout del negozio online.',
'StoreAdm_PG_Gw_Store_Id' => 'Store ID {gw}',
'StoreAdm_PG_Gw_Store_Password' => 'Store Password {gw}',
'StoreAdm_PG_Sandbox_Sslcommerz_Hint' => 'Se ATTIVO usa {sandbox} con credenziali sandbox; DISATTIVALO per addebitare clienti reali su {live}.',
'StoreAdm_PG_Sslcommerz_Info' => 'Checkout ospitato che copre carte, mobile banking bKash/Nagad/Rocket e internet banking in Bangladesh. Le credenziali provengono dal tuo pannello commerciante SSLCommerz (Store ID + Store Password / credenziali API).',
'StoreAdm_PG_Sslcommerz_Ipn_Url' => 'URL IPN (sistema di riserva consigliato: impostalo in My Stores → IPN Settings nel pannello commerciante SSLCommerz):',
'StoreAdm_PG_Sslcommerz_Disabled_Desc' => 'Attiva SSLCommerz e inserisci Store ID e Store Password (dal pannello commerciante SSLCommerz) per accettare carte, mobile banking e internet banking al checkout del negozio online.',
