'Cr_Guide_Meaning' => 'Significato',
'Cr_Guide_T_Statuses' => 'Stati',
'Cr_Guide_Statuses_Note' => 'Gli stati avanzano solo in avanti, quindi un aggiornamento in ritardo non riporta mai indietro un pacco. Un pacco consegnato può comunque essere segnalato come in rientro o reso.',
'Cr_Guide_S_booked' => 'Il corriere ha l\'ordine; nessuno lo ha ancora ritirato. Solo in questa fase la prenotazione può essere annullata.',
'Cr_Guide_S_picked_up' => 'Il corriere ha ritirato il pacco.',
'Cr_Guide_S_in_transit' => 'In transito tra hub, in dogana o in giacenza.',
'Cr_Guide_S_out_for_delivery' => 'Affidato al fattorino oggi.',
'Cr_Guide_S_failed_attempt' => 'Destinatario assente, rifiutato o indirizzo errato. Il corriere riprova o lo restituisce.',
'Cr_Guide_S_delivered' => 'Consegnato al cliente. L\'importo in contrassegno risulta incassato dal corriere.',
'Cr_Guide_S_returning' => 'In viaggio di ritorno verso di te.',
'Cr_Guide_S_returned' => 'Tornato da te: resta in Resi da verificare oppure viene rimesso in stock automaticamente.',
'Cr_Guide_S_cancelled' => 'La prenotazione è stata annullata.',
'Cr_Guide_T_Booking' => 'Prenotazione degli ordini',
'Cr_Guide_B_Booking' => 'Invia al corriere compila il modulo a partire dalla vendita: destinatario, indirizzo, l\'importo ancora da pagare come contrassegno e il peso dei prodotti. I corrieri con un proprio elenco di città mostrano un selettore, e la tua scelta viene ricordata per quella città. Aggregatori, DHL, FedEx, UPS e Lalamove offrono Confronta tariffe: scegli un prezzo e Prenota lo acquista. Più vendite possono essere prenotate insieme dall\'elenco vendite.',
'Cr_Guide_T_Cod' => 'Pagamento in contrassegno',
'Cr_Guide_B_Cod' => 'Un pacco in contrassegno passa da Non incassato a Incassato dal corriere (alla consegna) a Accreditato a te. I corrieri che comunicano gli accrediti aggiornano da soli l\'ultimo passaggio; per gli altri usa Aggiorna contrassegno. Se in Impostazioni corrieri è scelto un conto, l\'accredito viene registrato come pagamento sulla vendita. I costi del corriere possono essere salvati come spesa una volta concluso il pacco.',
'Cr_Guide_T_Returns' => 'Pacchi resi',
'Cr_Guide_B_Returns' => 'Per impostazione predefinita un pacco reso resta in Spedizioni corriere, sotto Resi da verificare. Rimetti in stock crea un reso di vendita per l\'intero ordine e riporta gli articoli in giacenza; Ignora non ripristina nulla, per pacchi danneggiati o smarriti. In alternativa, Impostazioni corrieri può rimettere in stock automaticamente.',
'Cr_Guide_T_Customers' => 'Messaggi ai clienti e pagina di tracciamento',
'Cr_Guide_B_Customers' => 'Le notifiche ai clienti in Impostazioni corrieri inviano SMS, email o WhatsApp agli stati che selezioni, una sola volta per pacco, con il tuo testo. La pagina di tracciamento nel negozio online consente ai clienti di seguire un pacco con il numero di tracciamento, oppure con il numero d\'ordine e il telefono. I clienti che rendono spesso i pacchi ricevono un badge di rischio di reso al momento della prenotazione.',
'Cr_Guide_T_Labels' => 'Etichette',
'Cr_Guide_B_Labels' => 'Stampa etichetta fornisce l\'etichetta del corriere quando ne emette una (un PDF, un link o un\'immagine), altrimenti un\'etichetta Stocky con il codice a barre di tracciamento e l\'importo da incassare. Per stampare, consenti i pop-up per questo sito. DHL, FedEx e UPS forniscono la loro etichetta una sola volta, alla prenotazione, e Stocky la conserva per le ristampe.',
'Cr_Guide_T_Faq' => 'Risoluzione dei problemi',
'Cr_Guide_Q_Test' => 'Il test di connessione non riesce',
'Cr_Guide_A_Test' => 'Le chiavi di test vanno con la modalità Test e le chiavi live con Live: sono diverse. Apri Log corrieri e leggi la risposta del corriere per conoscere il motivo esatto.',
'Cr_Guide_Q_City' => 'Il corriere rifiuta la città o l\'indirizzo',
'Cr_Guide_A_City' => 'Scegli la città dall\'elenco città del corriere nel modulo di prenotazione; i corrieri accettano solo i propri nomi. I corrieri che lavorano con indirizzi postali richiedono anche provincia/stato, CAP e codice paese di due lettere.',
'Cr_Guide_Q_Webhook' => 'Gli stati non cambiano da soli',
'Cr_Guide_A_Webhook' => 'Per i corrieri che inviano aggiornamenti, verifica che l\'URL del webhook sia registrato presso il corriere: Log corrieri mostra ogni aggiornamento ricevuto, oppure perché è stato rifiutato (ad esempio un secret errato). Gli altri corrieri vengono controllati secondo la pianificazione in Impostazioni corrieri, e Controlla stato ora effettua subito la richiesta.',
'Cr_Guide_Q_Stuck' => 'Una spedizione mostra un errore di controllo stato',
'Cr_Guide_A_Stuck' => 'Il corriere ha rifiutato gli ultimi controlli; il motivo è indicato sulla spedizione e in Log corrieri. Dopo ripetuti errori una spedizione non viene più controllata automaticamente: risolvi la causa, poi usa Controlla stato ora.',
'Cr_Guide_Q_Label' => 'Non si apre nulla quando stampo un\'etichetta',
'Cr_Guide_A_Label' => 'Il browser ha bloccato il pop-up. Consenti i pop-up per questo sito e riprova.',
'Cr_Guide_Q_Cod' => 'Un accredito in contrassegno non è stato registrato sulla vendita',
'Cr_Guide_A_Cod' => 'In Impostazioni corrieri, il pagamento in contrassegno richiede l\'interruttore attivo e un conto selezionato. Senza un conto, gli accrediti vengono solo segnati come accreditati.',
