'Tfa_Guide_Lead' => 'L\'autenticazione a due fattori (2FA) aggiunge un secondo passaggio all\'accesso: dopo la password, il personale digita un codice a 6 cifre da un\'app di autenticazione sul telefono. Una password rubata o indovinata non basta più per entrare.',
