'Tfa_Guide_Staff_Title' => 'Per ogni membro del personale',
'Tfa_Guide_App_Title' => 'Installa un\'app di autenticazione',
'Tfa_Guide_App_Text' => 'Funziona qualsiasi app che supporti i codici standard a 6 cifre (TOTP). Sono gratuite e funzionano offline:',
'Tfa_Guide_Enable_Title' => 'Attivala dal profilo',
'Tfa_Guide_Enable_1' => 'Apri Profilo (menu dell\'avatar in alto a destra) e trova la scheda "Autenticazione a due fattori".',
'Tfa_Guide_Enable_2' => 'Fai clic su "Attiva" e conferma con la password attuale.',
'Tfa_Guide_Enable_3' => 'Scansiona il codice QR con l\'app, oppure digita la chiave mostrata sotto di esso.',
'Tfa_Guide_Enable_4' => 'Inserisci il codice a 6 cifre mostrato dall\'app per completare.',
'Tfa_Guide_Open_Profile' => 'Apri il mio profilo',
'Tfa_Guide_Codes_Title' => 'Salva i codici di recupero',
'Tfa_Guide_Codes_Text' => 'Subito dopo la configurazione vengono mostrati una sola volta 8 codici di recupero. Ognuno sostituisce una sola volta un codice del telefono, in caso di telefono smarrito, guasto o ripristinato. Scaricali o copiali e conservali in un luogo sicuro, lontano dal telefono.',
'Tfa_Guide_Codes_Note' => 'Ne restano pochi? "Nuovi codici di recupero" nel profilo sostituisce l\'intero set; i vecchi codici smettono di funzionare.',
'Tfa_Guide_Signin_Title' => 'Accesso',
'Tfa_Guide_Signin_Text' => 'Dopo email e password, la pagina di accesso chiede il codice attuale dall\'app. I codici cambiano ogni 30 secondi e ognuno funziona una sola volta.',
'Tfa_Guide_Signin_Trust' => 'Selezionando "Non chiedere più su questo dispositivo" il codice non viene richiesto su quel browser per :days giorni.',
'Tfa_Guide_Signin_Recovery' => 'Non hai il telefono a portata di mano? Fai clic su "Usa un codice di recupero" e digita uno dei codici salvati.',
'Tfa_Guide_Admin_Title' => 'Per gli amministratori',
'Tfa_Guide_Require_Title' => 'Rendila obbligatoria',
'Tfa_Guide_Require_Text' => 'Attiva "Richiedi l\'autenticazione a due fattori" in questa scheda, poi scegli i ruoli che devono usarla, oppure lascia l\'elenco vuoto per tutti gli utenti. Fai clic su Invia per salvare.',
'Tfa_Guide_Require_Next' => 'Nessuno viene disconnesso. Gli utenti che non hanno ancora la 2FA vengono guidati nella configurazione sulla pagina di accesso al loro prossimo accesso, prima di entrare, e lì vedono i propri codici di recupero.',
'Tfa_Guide_Require_Note' => 'Gli utenti per cui è obbligatoria non possono disattivarla dal proprio profilo.',
'Tfa_Guide_Trust_Title' => 'Dispositivi attendibili',
'Tfa_Guide_Trust_Text' => '"Ricorda i dispositivi attendibili" stabilisce per quanto tempo un browser può saltare il codice dopo un accesso riuscito. Scegli "Chiedi sempre un codice" per computer condivisi o pubblici, come un POS in negozio.',
'Tfa_Guide_Trust_Note' => 'Ridurre il numero accorcia anche la durata dei dispositivi già attendibili; disattivare o reimpostare la 2FA li fa dimenticare tutti.',
'Tfa_Guide_Lost_Title' => 'Telefono smarrito e nessun codice di recupero',
'Tfa_Guide_Lost_Text' => 'Nella pagina Utenti, gli utenti con 2FA mostrano "Attiva" nella colonna 2FA. Il pulsante con lo scudo in Azioni la reimposta: l\'utente accede solo con la password e configura di nuovo l\'app (o gli viene chiesto di farlo, se è obbligatoria).',
'Tfa_Guide_Lost_Warn' => 'Verifica l\'identità di chi lo richiede prima di reimpostare: una reimpostazione rimuove la protezione che la 2FA offre a quell\'account.',
'Tfa_Guide_Open_Users' => 'Apri Utenti',
'Tfa_Guide_Mobile_Title' => 'App mobile e API',
'Tfa_Guide_Mobile_Text' => 'L\'app mobile e l\'endpoint dei token API richiedono lo stesso codice. Se la 2FA è obbligatoria per un utente che non l\'ha ancora configurata, deve accedere una volta dal web per farlo.',
'Tfa_Guide_Protect_Title' => 'Protezione integrata',
'Tfa_Guide_Protect_1' => '5 codici errati bloccano l\'inserimento dei codici per quell\'utente per 15 minuti, indipendentemente dalle impostazioni di blocco qui sopra.',
'Tfa_Guide_Protect_2' => 'Ogni codice e ogni codice di recupero funziona una sola volta.',
'Tfa_Guide_Protect_3' => 'Con "Registra l\'attività di accesso" attivo, i codici errati compaiono nell\'elenco Attività di accesso come "Codice 2FA errato".',
'Tfa_Guide_Trouble_Title' => 'Risoluzione dei problemi',
'Tfa_Guide_Faq_Clock_Q' => '“Il codice non è valido” con un codice appena generato',
'Tfa_Guide_Faq_Clock_A' => 'Probabilmente l\'orologio del telefono non è preciso. I codici dipendono dall\'ora: imposta data e ora del telefono su automatico (ora di rete), poi prova il codice successivo.',
'Tfa_Guide_Faq_Phone_Q' => 'Passaggio a un nuovo telefono',
'Tfa_Guide_Faq_Phone_A' => 'Usa la funzione di trasferimento dell\'app di autenticazione, oppure disattiva la 2FA dal profilo e riattivala con il nuovo telefono (se è obbligatoria, chiedi invece a un amministratore di reimpostarla).',
'Tfa_Guide_Faq_Locked_Q' => '“Troppi codici non validi”',
'Tfa_Guide_Faq_Locked_A' => 'Attendi il tempo indicato (fino a 15 minuti), oppure chiedi a un amministratore di reimpostare la 2FA dell\'utente.',
'Tfa_Guide_Faq_Key_Q' => 'Nessuno con la 2FA riesce ad accedere dopo un trasferimento del server',
'Tfa_Guide_Faq_Key_A' => 'I segreti 2FA sono crittografati con l\'APP_KEY presente nel file .env. Mantieni la stessa APP_KEY quando sposti o ripristini l\'applicazione; se è cambiata, un amministratore senza 2FA deve reimpostare gli utenti interessati.',
