'Tfa_Guide_Rollout_Title' => 'Estendila a tutti gli utenti',
'Tfa_Guide_Rollout_1' => 'Attivala prima per il tuo account (Profilo), così conosci i passaggi.',
'Tfa_Guide_Rollout_2' => 'Comunica al tuo team quale app installare e che la configurazione richiede un minuto all\'accesso.',
'Tfa_Guide_Rollout_3' => 'Attiva "Richiedi l\'autenticazione a due fattori", lascia vuoto "Obbligatoria per" (= tutti gli utenti) e, se vuoi, scegli un periodo di tolleranza. Fai clic su Invia.',
'Tfa_Guide_Rollout_4' => 'Fai clic su "Disconnetti gli utenti senza 2FA" in modo che chi ha già effettuato l\'accesso la configuri subito anziché a un accesso successivo. Tu resti connesso.',
'Tfa_Guide_Rollout_5' => 'Segui l\'avanzamento con il contatore in questa scheda, oppure con il filtro "Da configurare" nella pagina Utenti.',
'Tfa_Guide_Rollout_Note' => 'Con un periodo di tolleranza, la schermata di configurazione mostra “Ricordamelo più tardi” fino alla scadenza; dopo, la configurazione è necessaria per accedere.',
'Tfa_Guide_Customers_Title' => 'Account dei clienti (negozio e portale clienti)',
'Tfa_Guide_Customers_Text' => 'Anche i clienti possono proteggere i propri account. È facoltativa per ogni cliente e mai imposta: attivala in Impostazioni negozio → Controllo accesso alla registrazione (negozio online) e in Portale clienti → Impostazioni portale (portale clienti).',
'Tfa_Guide_Customers_1' => 'I clienti la attivano da Il mio account (negozio) o Profilo (portale).',
'Tfa_Guide_Customers_2' => 'Scelgono un codice inviato via email (il metodo più semplice, senza app) oppure un\'app di autenticazione con codici di recupero.',
'Tfa_Guide_Customers_3' => 'I codici via email richiedono impostazioni di posta funzionanti (Impostazioni → Impostazioni email). Scadono dopo 10 minuti.',
'Tfa_Guide_Customers_4' => 'Disattivando l\'opzione in seguito si bloccano le nuove configurazioni; ai clienti che la usano già continua a essere richiesta e possono disattivarla da soli.',
